<?php
use App\DB;
$row=DB::one('SELECT s.*,q.quote_number,q.issue_date,q.valid_until,q.company_snapshot,q.customer_snapshot,q.subtotal,q.discount_amount,q.tax_amount,q.total,q.prepayment,q.payable,q.notes,q.terms FROM quote_shares s JOIN quotes q ON q.id=s.quote_id WHERE s.token_hash=? AND s.revoked_at IS NULL AND s.expires_at>NOW()',[''.hash('sha256',$shareToken)]);
$error='';$allowed=false;$key='share_ok_'.$shareToken;$attemptKey='share_attempts_'.$shareToken;
if($row){if(!empty($_SESSION[$key]))$allowed=true;elseif($_SERVER['REQUEST_METHOD']==='POST'){if((int)($_SESSION[$attemptKey]??0)>=8)$error='تعداد تلاش بیش از حد مجاز است؛ مرورگر را بسته و کمی بعد دوباره تلاش کنید.';elseif(password_verify((string)($_POST['password']??''),$row['password_hash'])){$_SESSION[$key]=true;unset($_SESSION[$attemptKey]);$allowed=true;DB::exec('UPDATE quote_shares SET view_count=view_count+1,last_viewed_at=NOW() WHERE id=?',[$row['id']]);}else{$_SESSION[$attemptKey]=(int)($_SESSION[$attemptKey]??0)+1;$error='رمز مشاهده نادرست است.';}}}
if(!$row){http_response_code(404);$error='این لینک معتبر نیست، منقضی شده یا توسط صادرکننده لغو شده است.';}
$company=$row?json_decode($row['company_snapshot'],true):[];$customer=$row?json_decode($row['customer_snapshot'],true):[];$items=$allowed?DB::all('SELECT * FROM quote_items WHERE quote_id=? ORDER BY sort_order,id',[$row['quote_id']]):[];
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مشاهده پیش‌فاکتور</title><style>*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#111;font-family:Tahoma,sans-serif}.wrap{width:min(1100px,calc(100% - 24px));margin:24px auto}.card,.sheet{background:#fff;border:1px solid #ccd3dc;border-radius:12px;padding:24px}.card{max-width:420px;margin:10vh auto;text-align:center}input,button{font:inherit;padding:11px;border-radius:8px;border:1px solid #bbb;width:100%;margin-top:12px}button{background:#2563eb;color:#fff;border:0}.head{display:grid;grid-template-columns:1fr 1fr 1fr;align-items:center;border-bottom:2px solid #111;padding-bottom:12px}.head h1{text-align:center;font-size:20px}.meta{line-height:2}.party{border:1px solid #111;border-radius:7px;margin-top:12px;padding:12px;line-height:2}.party h2{font-size:14px;margin:0}.items{width:100%;border-collapse:collapse;margin-top:12px}.items th,.items td{border:1px solid #111;padding:7px;font-size:12px;text-align:center}.sign{display:grid;grid-template-columns:1fr 1fr;min-height:110px;border:1px solid #111;margin-top:12px;text-align:center;padding:15px}.tools{text-align:center;margin:12px}.tools button{width:auto}@media print{body{background:#fff}.tools{display:none}.wrap{width:100%;margin:0}.sheet{border:0;border-radius:0}}</style></head><body><?php if(!$allowed):?><form class="card" method="post"><h2>مشاهده امن پیش‌فاکتور</h2><p><?=e($error?:'رمز شش‌رقمی ارسال‌شده را وارد کنید.')?></p><?php if($row):?><input name="password" inputmode="numeric" maxlength="6" required autofocus placeholder="رمز مشاهده"><button>نمایش پیش‌فاکتور</button><?php endif;?></form><?php else:?><div class="tools"><button onclick="print()">چاپ / ذخیره PDF</button></div><main class="wrap sheet"><header class="head"><div><b><?=e($company['legal_name']??$company['name']??'')?></b></div><h1>پیش‌فاکتور فروش کالا و خدمات</h1><div class="meta">شماره: <?=e($row['quote_number'])?><br>تاریخ: <?=e($row['issue_date'])?></div></header><section class="party"><h2>فروشنده</h2><?=e($company['address']??'')?> — تلفن: <?=e($company['phone']??$company['mobile']??'')?> — شناسه ملی: <?=e($company['national_id']??'')?></section><section class="party"><h2>خریدار</h2><?=e($customer['name']??'')?> — تلفن: <?=e($customer['phone']??$customer['mobile']??'')?> — شناسه ملی: <?=e($customer['national_id']??'')?><br><?=e($customer['address']??'')?></section><table class="items"><thead><tr><th>ردیف</th><th>شرح</th><th>واحد</th><th>تعداد</th><th>مبلغ واحد</th><th>جمع</th></tr></thead><tbody><?php foreach($items as $i=>$item):?><tr><td><?=$i+1?></td><td><?=e($item['name'])?></td><td><?=e($item['unit'])?></td><td><?=number_format((float)$item['quantity'])?></td><td><?=number_format((float)$item['unit_price'])?></td><td><?=number_format((float)$item['line_total'])?></td></tr><?php endforeach;?><tr><th colspan="5">مبلغ قابل پرداخت</th><th><?=number_format((float)$row['payable'])?> ریال</th></tr></tbody></table><section class="party"><b>توضیحات:</b> <?=e($row['notes']??'-')?><br><b>شرایط پرداخت:</b> <?=e($row['terms']??'-')?></section><div class="sign"><div>مهر و امضای فروشنده</div><div>مهر و امضای خریدار</div></div></main><?php endif;?></body></html>
